SELECT

FROM marketing_flash_activity


        AND title LIKE CONCAT('%', #{keyword,jdbcType=VARCHAR}, '%')


        AND end_date >= #{startDate,jdbcType=DATE}


        AND start_date <= #{endDate,jdbcType=DATE}


        AND status = #{status,jdbcType=TINYINT}


ORDER BY id DESC

